class LedgerExporter implements Runnable {
    private boolean leader;                 // 1. written by the election callback thread
    private boolean running = true;         // 2. written by the shutdown hook thread

    @Override
    public void run() {
        while (running) {                   // 3. both flags read in a hot loop
            if (leader) exportBatch();
        }
    }

    void onElected() { leader = true; }
    void stop() { running = false; }
}

