class LedgerExporter implements Runnable {
    private volatile boolean leader;            // 1. both flags cross threads: both volatile
    private volatile boolean running = true;

    @Override
    public void run() {
        try {
            while (running) {                   // 2. re-read on every pass
                if (leader) {
                    exportBatch();
                } else {
                    Thread.sleep(50);           // 3. a standby doesn't need a whole core
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // 4. treat an interrupt as a stop, too
        }
    }

    void onElected() { leader = true; }
    void stop() { running = false; }
}

