public class Poller implements Runnable {
    private volatile boolean running = true;   // volatile: the loop re-reads it, the write is visible

    @Override
    public void run() {
        while (running) {
            pollOnce();
        }
    }

    public void shutdown() {
        running = false;
    }

    private void pollOnce() { /* fetch and handle one batch */ }
}

// With a plain boolean, nothing links the write in shutdown() to the read in run(),
// so the JIT may read the field once and loop forever.

